// Verify sort logic: descending numeric sort with -c
// If we have records with שכירות: 5000, 3000, 7000
const mockRecords = [
  { 'שכירות': '5000', '__id': '1' },
  { 'שכירות': '3000', '__id': '2' },
  { 'שכירות': '7000', '__id': '3' },
];

// Simulate the sort comparator from px1.dart
const comparator = (a, b) => {
  const getField = (r) => r['שכירות'];
  const x = getField(a) ?? '', y = getField(b) ?? '';
  if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
  const nx = Number.parseFloat(x), ny = Number.parseFloat(y);
  let c;
  if (!isNaN(nx) && !isNaN(ny)) {
    c = nx < ny ? -1 : nx > ny ? 1 : 0;
  } else {
    c = x < y ? -1 : x > y ? 1 : 0;
  }
  if (c != 0) return -c;  // Descending: return -c
  return 0;
};

const sorted = mockRecords.sort(comparator);
console.log('Original order: 5000, 3000, 7000');
console.log('Sorted (descending):');
sorted.forEach(r => console.log('  ' + r['שכירות']));
console.log('Expected: 7000, 5000, 3000');
console.log('Match:', sorted[0]['שכירות'] === '7000' && sorted[1]['שכירות'] === '5000' && sorted[2]['שכירות'] === '3000' ? '✓' : '✗');
EOF
